using System.Text.Json;
using KernelOS.Core;
using KernelOS.Core.Execution;
using KernelOS.Core.Filesystem;
namespace KernelOS.Tools;
public sealed class FilesystemTool(IFilesystemCapability? filesystem = null) : IKernelTool
{ public string Name=>"filesystem"; public string Description=>"Performs read-only filesystem operations."; public string Category=>"filesystem"; public IReadOnlyCollection<ToolCapability> Capabilities=>[new("Search",""),new("Exists",""),new("Metadata",""),new("Resolve",""),new("ListDirectory","")]; public IReadOnlyCollection<ToolParameter> Parameters=>[new("operation","Read-only operation.","string",true),new("path","Path to validate.","string",true)]; public ToolExecutionMetadata ExecutionMetadata=>new(true,false,false,ExecutionRiskLevel.Low); public async Task<ToolExecutionResult> ExecuteAsync(ToolExecutionRequest request,CancellationToken cancellationToken=default){if(!request.Arguments.TryGetValue("operation",out var op)||op.ValueKind!=JsonValueKind.String)return ToolExecutionResult.InvalidArguments("operation is required.");if(filesystem is null)return ToolExecutionResult.Failure("Filesystem capability is unavailable.");var result=await filesystem.ExecuteAsync(op.GetString()!,request.Arguments,cancellationToken);return result.Success?ToolExecutionResult.Success("Filesystem operation completed.",JsonSerializer.SerializeToElement(result.Data)):result.Error=="unauthorized"?new(ToolExecutionStatus.Unauthorized,"The path is not authorized."):result.Error=="not_found"?ToolExecutionResult.NotFound("The path was not found."):ToolExecutionResult.InvalidArguments("The filesystem request is invalid.");} }
